diff --git a/apps/web/app/api/v3/feedbackRecords/lib/access.ts b/apps/web/app/api/v3/feedbackRecords/lib/access.ts
--- a/apps/web/app/api/v3/feedbackRecords/lib/access.ts
+++ b/apps/web/app/api/v3/feedbackRecords/lib/access.ts
@@ -0,0 +1,194 @@
+import "server-only";
+import type { logger } from "@formbricks/logger";
+import { requireUnifyFeedbackWorkspaceAccess } from "@/app/api/v3/lib/feedback-access";
+import { problemBadRequest, problemForbidden, problemUnprocessableContent } from "@/app/api/v3/lib/response";
+import type { TV3Authentication } from "@/app/api/v3/lib/types";
+import { getFeedbackDirectoriesByWorkspaceId } from "@/modules/ee/feedback-directory/lib/feedback-directory";
+import { retrieveFeedbackRecord } from "@/modules/hub/service";
+import type { FeedbackRecordData } from "@/modules/hub/types";
+import { hubErrorToProblemResponse } from "./errors";
+
+/**
+ * Tenant isolation for the feedback-records surface. Two guards live here, and every operation goes
+ * through at least one of them:
+ *
+ * - `resolveWorkspaceFeedbackTenant` — the workspace → dataset → Hub tenant choke point.
+ * - `requireOwnedFeedbackRecord` — the per-record ownership check for the Hub endpoints that take a bare
+ *   record id and derive the tenant from the record itself.
+ *
+ * Kept in its own module (mirroring `unify-feedback/taxonomy/lib/access.ts`) so the authorization rules
+ * are reviewable in one place instead of being spread across the operations.
+ */
+
+type TResolveParams = {
+  authentication: TV3Authentication;
+  workspaceId: string;
+  minPermission: "read" | "readWrite";
+  requestId: string;
+  instance: string;
+  datasetId?: string;
+};
+
+export type TResolvedFeedbackTenant = {
+  workspaceId: string;
+  organizationId: string;
+  tenantId: string;
+  /** Name of the resolved dataset, echoed to the caller so a response is self-describing. */
+  datasetName: string;
+  allowedTenantIds: string[];
+};
+
+type TResolveResult = ({ ok: true } & TResolvedFeedbackTenant) | { ok: false; response: Response };
+
+/**
+ * Resolve (and authorize) the Hub tenant for a feedback-records request. This is the single tenant-
+ * isolation choke point for every tool: workspace access → feedback-directories license gate →
+ * dataset membership → the resolved Hub tenant (= the FeedbackDirectory id, `dataset_id` on the wire).
+ * Mirrors the Unify read path (`modules/ee/unify-feedback/page.tsx`). `tenant_id` is never taken from caller input.
+ */
+export async function resolveWorkspaceFeedbackTenant({
+  authentication,
+  workspaceId,
+  minPermission,
+  requestId,
+  instance,
+  datasetId,
+}: TResolveParams): Promise<TResolveResult> {
+  const authResult = await requireUnifyFeedbackWorkspaceAccess(
+    authentication,
+    workspaceId,
+    minPermission,
+    requestId,
+    instance
+  );
+  if (authResult instanceof Response) {
+    return { ok: false, response: authResult };
+  }
+
+  const { workspaceId: resolvedWorkspaceId, organizationId } = authResult;
+
+  const directories = await getFeedbackDirectoriesByWorkspaceId(resolvedWorkspaceId);
+  // Normalised once, here: the Hub uses `tenant_id` verbatim — in SQL filters and, for semantic search, in
+  // the vector query — with no trimming of its own, so a stray space silently matches nothing instead of
+  // failing. Doing it at the source means every consumer gets a usable value; doing it per call site meant
+  // whichever site was written last got it right.
+  const allowedTenantIds = directories.map((directory) => directory.id.trim());
+
+  if (datasetId) {
+    const requested = directories.find((directory) => directory.id === datasetId);
+    if (!requested) {
+      return {
+        ok: false,
+        response: problemForbidden(
+          requestId,
+          "You are not authorized to access this feedback dataset",
+          instance
+        ),
+      };
+    }
+    return {
+      ok: true,
+      workspaceId: resolvedWorkspaceId,
+      organizationId,
+      tenantId: requested.id.trim(),
+      datasetName: requested.name,
+      allowedTenantIds,
+    };
+  }
+
+  if (allowedTenantIds.length === 0) {
+    return {
+      ok: false,
+      // Actionable on purpose: an agent hitting this can only help if the response says who has to do
+      // what, and where. Datasets are organization-level, so a workspace member cannot self-serve.
+      response: problemUnprocessableContent(
+        requestId,
+        "No feedback dataset is assigned to this workspace. An organization owner or manager can create one and grant this workspace access under Settings → Organization → Feedback Datasets.",
+        { instance }
+      ),
+    };
+  }
+  if (allowedTenantIds.length > 1) {
+    return {
+      ok: false,
+      response: problemBadRequest(
+        requestId,
+        "Multiple feedback datasets are assigned to this workspace; specify datasetId",
+        { instance }
+      ),
+    };
+  }
+
+  return {
+    ok: true,
+    workspaceId: resolvedWorkspaceId,
+    organizationId,
+    tenantId: directories[0].id.trim(),
+    datasetName: directories[0].name,
+    allowedTenantIds,
+  };
+}
+
+type TRequireOwnedRecordParams = {
+  feedbackRecordId: string;
+  resolution: TResolvedFeedbackTenant;
+  /** Set when the caller pinned a dataset: the record must then live in *that* one, not merely in a permitted one. */
+  datasetId?: string;
+  log: ReturnType<typeof logger.withContext>;
+  requestId: string;
+  instance: string;
+};
+
+type TOwnedRecordResult = { ok: true; record: FeedbackRecordData } | { ok: false; response: Response };
+
+/**
+ * Assert that a feedback record belongs to the caller, and return it.
+ *
+ * Several Hub endpoints (`GET /{id}`, `GET /{id}/similar`, `DELETE /{id}`) take a bare record id and
+ * derive the tenant from the stored record — the Hub delegates record-level authorization to us by
+ * design. Without this guard each of them would be a cross-tenant primitive: a read oracle, a
+ * neighbour-leak, and a destructive write respectively. So every one of them retrieves first, checks the
+ * record's tenant against the caller's permitted set, and only then acts.
+ *
+ * A missing record and a foreign record return the *same* generic 403, so record ids can't be probed
+ * across tenants. The response is identical per route, not per resource.
+ */
+export async function requireOwnedFeedbackRecord({
+  feedbackRecordId,
+  resolution,
+  datasetId,
+  log,
+  requestId,
+  instance,
+}: TRequireOwnedRecordParams): Promise<TOwnedRecordResult> {
+  const result = await retrieveFeedbackRecord(feedbackRecordId);
+  if (result.error || !result.data) {
+    const status = result.error?.status ?? 0;
+    // Not found → generic 403, no existence oracle across tenants.
+    if (status === 404) {
+      // Logged like the tenant-mismatch denial below, so both halves of the 403 are observable.
+      log.warn({ statusCode: 403, hubStatus: 404 }, "Feedback record not found");
+      return { ok: false, response: forbidFeedbackRecord(requestId, instance) };
+    }
+    log.warn({ hubStatus: status, hubCode: result.error?.code }, "Hub retrieveFeedbackRecord failed");
+    return { ok: false, response: hubErrorToProblemResponse(result.error, requestId, instance) };
+  }
+
+  // When the caller named a dataset, the record must live in THAT one; otherwise any dataset the
+  // workspace owns is acceptable. Same 403 either way — see the doc comment above.
+  const permittedTenantIds = datasetId ? [resolution.tenantId] : resolution.allowedTenantIds;
+  if (!result.data.tenant_id || !permittedTenantIds.includes(result.data.tenant_id)) {
+    log.warn({ statusCode: 403 }, "Feedback record tenant outside caller's workspace datasets");
+    return { ok: false, response: forbidFeedbackRecord(requestId, instance) };
+  }
+
+  return { ok: true, record: result.data };
+}
+
+/**
+ * The single record-level 403. Exported so every path that must be indistinguishable from the others —
+ * the ownership guard above, and a record that vanishes mid-update — produces a byte-identical body by
+ * construction rather than by two copies of the same string staying in sync.
+ */
+export const forbidFeedbackRecord = (requestId: string, instance: string): Response =>
+  problemForbidden(requestId, "You are not authorized to access this feedback record", instance);

diff --git a/apps/web/app/api/v3/feedbackRecords/lib/errors.ts b/apps/web/app/api/v3/feedbackRecords/lib/errors.ts
--- a/apps/web/app/api/v3/feedbackRecords/lib/errors.ts
+++ b/apps/web/app/api/v3/feedbackRecords/lib/errors.ts
@@ -0,0 +1,149 @@
+import "server-only";
+import type { z } from "zod";
+import type { logger } from "@formbricks/logger";
+import { DatabaseError, ResourceNotFoundError } from "@formbricks/types/errors";
+import {
+  type InvalidParam,
+  problemBadGateway,
+  problemBadRequest,
+  problemConflict,
+  problemForbidden,
+  problemInternalError,
+  problemPayloadTooLarge,
+  problemServiceUnavailable,
+  problemTooManyRequests,
+  problemUnprocessableContent,
+} from "@/app/api/v3/lib/response";
+import type { HubError } from "@/modules/hub/utils";
+
+/**
+ * Error mapping for the feedback-records surface: Hub failures and unexpected throws → controlled v3
+ * problem responses. Split out of `operations.ts` so the operations read as a dispatcher and the mapping
+ * rules — the part with the disclosure risk — can be tested on their own.
+ */
+
+// Bounds on what a Hub 4xx may contribute to our response body (see `hubErrorToProblemResponse`).
+const MAX_RELAYED_INVALID_PARAMS = 20;
+const MAX_RELAYED_DETAIL_LENGTH = 512;
+
+/**
+ * Semantic search and similarity need embeddings, which are optional in the Hub. Our own static message,
+ * not the upstream body: it names the setting to change, on both processes that need it.
+ */
+export const EMBEDDINGS_UNAVAILABLE_DETAIL =
+  "Semantic search is not available: the feedback service has no embedding model configured. A self-hosting administrator can enable it by setting EMBEDDING_PROVIDER and EMBEDDING_MODEL on both the Hub API and the Hub worker.";
+
+/**
+ * A record that exists and belongs to the caller, yet has no embedding — the only thing a Hub 404 can
+ * mean once ownership is proven. Reported as 409, not 404, because the record *is* there; the message
+ * distinguishes the two causes, because only one of them is worth retrying (a fresh record is still being
+ * embedded, whereas a record with no text has no embedding to wait for).
+ */
+export const EMBEDDING_PENDING_DETAIL =
+  "This feedback record has no embedding, so similar records cannot be found. If it was just created, embeddings are generated in the background — retry in a moment. If it has no text, or its text was cleared by an update, it has no embedding at all and retrying will not help.";
+
+/**
+ * Hub statuses whose detail describes the *caller's own* request, and may therefore be echoed: a rejected
+ * field value, a duplicate submission, an oversized record.
+ *
+ * Deliberately not "any 4xx". A Hub 401/403 means *our* Hub credentials were refused and a 404 can reveal
+ * upstream addressing — neither is the caller's business, and both would be describing our infrastructure
+ * rather than their request.
+ */
+const RELAYABLE_HUB_STATUSES = new Set([400, 409, 413, 422]);
+
+/**
+ * The one place that decides what a Hub failure may say to a caller.
+ *
+ * The Hub owns content rules we deliberately don't duplicate (NULL bytes, its own length limits), so for
+ * the statuses above its message is relayed — bounded — because without it an agent cannot correct its own
+ * request. Everything else is replaced by a fixed string. Used both for whole-request problem responses and
+ * for the per-record failures of a batch write, so neither can drift into leaking more than the other.
+ */
+export function relayableHubDetail(error: HubError | null, fallback: string): string {
+  if (!error?.problemDetail || !RELAYABLE_HUB_STATUSES.has(error.status)) {
+    return fallback;
+  }
+  return error.problemDetail.slice(0, MAX_RELAYED_DETAIL_LENGTH);
+}
+
+/**
+ * Map a Hub service error to a controlled v3 problem response.
+ *
+ * A Hub 400/422 describes the *caller's own* input, so its field-level detail is relayed: the Hub owns
+ * the content rules we deliberately don't duplicate here (NULL bytes, its own length limits), and
+ * without them an agent can't correct its request. Everything else —
+ * unconfigured/unreachable Hub, our own Hub credentials being rejected, upstream 5xx — collapses to a
+ * generic 502 and is only ever logged, never echoed.
+ */
+export function hubErrorToProblemResponse(
+  error: HubError | null,
+  requestId: string,
+  instance: string
+): Response {
+  const status = error?.status ?? 0;
+  if (status === 429) {
+    return problemTooManyRequests(requestId, "The feedback service is rate limiting requests.");
+  }
+
+  // A duplicate (submission_id, field_id) or an in-progress tenant purge — the caller's request, not an
+  // outage, and retryable in the purge case. Reported as 409 so an agent doesn't retry-loop on a 502.
+  if (status === 409) {
+    return problemConflict(
+      requestId,
+      relayableHubDetail(error, "The feedback service reported a conflict."),
+      instance
+    );
+  }
+
+  // The Hub's body cap is lower than ours, so this is reachable with a large (but locally valid) payload.
+  if (status === 413) {
+    return problemPayloadTooLarge(requestId, "The feedback record is too large.", instance);
+  }
+
+  // Embeddings are optional in the Hub, and the search endpoints are the only ones that need them. A
+  // deployment-level "not enabled", not an outage — so it must not collapse into the generic 502 below,
+  // which would read as "retry later" for something no retry can fix.
+  if (status === 503) {
+    return problemServiceUnavailable(requestId, EMBEDDINGS_UNAVAILABLE_DETAIL, instance);
+  }
+
+  if (status === 400 || status === 422) {
+    // Only name/reason cross over: the Hub's `code` vocabulary is its own, not the v3 InvalidParamCode set.
+    // Bounded on both axes — the Hub is a remote service, so we don't let it size our response body.
+    const invalidParams: InvalidParam[] | undefined = error?.invalidParams
+      ?.slice(0, MAX_RELAYED_INVALID_PARAMS)
+      .map(({ name, reason }) => ({
+        name: name.slice(0, MAX_RELAYED_DETAIL_LENGTH),
+        reason: reason.slice(0, MAX_RELAYED_DETAIL_LENGTH),
+      }));
+    const detail = relayableHubDetail(error, "The feedback service rejected the request.");
+
+    return status === 400
+      ? problemBadRequest(requestId, detail, { instance, invalid_params: invalidParams })
+      : problemUnprocessableContent(requestId, detail, { instance, invalid_params: invalidParams });
+  }
+
+  return problemBadGateway(requestId, "The feedback service is unavailable.", instance);
+}
+
+export function handleUnexpectedError(
+  err: unknown,
+  log: ReturnType<typeof logger.withContext>,
+  requestId: string,
+  instance: string
+): Response {
+  if (err instanceof ResourceNotFoundError) {
+    log.warn({ statusCode: 403, errorCode: err.name }, "Resource not found");
+    return problemForbidden(requestId, "You are not authorized to access this resource", instance);
+  }
+  if (err instanceof DatabaseError) {
+    log.error({ error: err, statusCode: 500 }, "Database error");
+    return problemInternalError(requestId, "An unexpected error occurred.", instance);
+  }
+  log.error({ error: err, statusCode: 500 }, "Unexpected error");
+  return problemInternalError(requestId, "An unexpected error occurred.", instance);
+}
+
+export const toInvalidParams = (error: z.ZodError): InvalidParam[] =>
+  error.issues.map((issue) => ({ name: issue.path.join("."), reason: issue.message }));

diff --git a/apps/web/app/api/v3/feedbackRecords/lib/serializers.ts b/apps/web/app/api/v3/feedbackRecords/lib/serializers.ts
--- a/apps/web/app/api/v3/feedbackRecords/lib/serializers.ts
+++ b/apps/web/app/api/v3/feedbackRecords/lib/serializers.ts
@@ -0,0 +1,132 @@
+import type {
+  FeedbackRecordData,
+  SemanticSearchResultItem,
+  SimilarRecordsResultItem,
+} from "@/modules/hub/types";
+
+/** The two similarity endpoints return the same row shape; either is acceptable here. */
+type FeedbackRecordMatchSource = SemanticSearchResultItem | SimilarRecordsResultItem;
+
+/**
+ * Public DTO for a feedback record. Field names mirror the Hub's feedback-record contract (snake_case)
+ * so the MCP surface, the Unify UI, and the Hub API documentation all describe the same shape.
+ *
+ * One deliberate exception: the Hub's `tenant_id` is emitted as **`dataset_id`**. The value is the same
+ * (a `FeedbackDirectory.id`), but "tenant" is Hub-internal vocabulary — the product, its UI and its docs
+ * call this a Feedback Dataset, so that is what the outward-facing surface says. Internal code keeps the
+ * `feedbackDirectory*` names; this serializer is the one place the outbound mapping happens.
+ *
+ * This is an explicit allowlist (not a pass-through of the SDK object): only the documented Hub fields
+ * are ever emitted, so a future SDK/bridge addition can't silently widen the response (OWASP API3).
+ * Read-only enrichment fields (sentiment/emotions/translation) are included when present.
+ */
+export type TV3FeedbackRecord = {
+  id: string;
+  dataset_id?: string;
+  submission_id?: string;
+  source_type?: string;
+  source_id?: string;
+  source_name?: string;
+  field_id?: string;
+  field_type?: string;
+  field_label?: string;
+  field_group_id?: string;
+  field_group_label?: string;
+  user_id?: string;
+  language?: string;
+  value_text?: string | null;
+  value_number?: number;
+  value_boolean?: boolean;
+  value_date?: string;
+  value_id?: string | null;
+  metadata?: Record<string, unknown>;
+  sentiment?: string;
+  sentiment_score?: number;
+  emotions?: string[] | string | null;
+  translation_lang_key?: string | null;
+  value_text_translated?: string | null;
+  collected_at?: string;
+  created_at?: string;
+  updated_at?: string;
+};
+
+// Allowlisted optional fields copied verbatim from the Hub record when present (explicit nulls
+// preserved). `tenant_id` is absent on purpose — it is renamed to `dataset_id` below.
+const FEEDBACK_RECORD_FIELDS = [
+  "submission_id",
+  "source_type",
+  "source_id",
+  "source_name",
+  "field_id",
+  "field_type",
+  "field_label",
+  "field_group_id",
+  "field_group_label",
+  "user_id",
+  "language",
+  "value_text",
+  "value_number",
+  "value_boolean",
+  "value_date",
+  "value_id",
+  "metadata",
+  "sentiment",
+  "sentiment_score",
+  "emotions",
+  "translation_lang_key",
+  "value_text_translated",
+  "collected_at",
+  "created_at",
+  "updated_at",
+] as const;
+
+export const serializeV3FeedbackRecord = (record: FeedbackRecordData): TV3FeedbackRecord => {
+  const source = record as unknown as Record<string, unknown>;
+  const dto: TV3FeedbackRecord = { id: record.id };
+  const writable = dto as Record<string, unknown>;
+
+  // The Hub's tenant is our dataset — same value, outward-facing name.
+  if (record.tenant_id !== undefined) {
+    dto.dataset_id = record.tenant_id;
+  }
+
+  for (const key of FEEDBACK_RECORD_FIELDS) {
+    if (source[key] !== undefined) {
+      writable[key] = source[key];
+    }
+  }
+  return dto;
+};
+
+/**
+ * One scored match from a similarity search. The Hub returns an identical row shape for text search and
+ * for "records like this one", so both go through this serializer.
+ *
+ * Only the fields needed to triage a hit are emitted — the id (to fetch the full record), the score, and
+ * the embedded text with its field label. Hydrating each hit into a full record would cost one Hub call
+ * per result; the caller can do that selectively via the get operation.
+ */
+export type TV3FeedbackRecordMatch = {
+  feedback_record_id: string;
+  /** Cosine similarity, 0 (unrelated) to 1 (identical). Results are ordered best first. */
+  score: number;
+  field_label: string;
+  value_text: string;
+};
+
+export const serializeV3FeedbackRecordMatch = (match: FeedbackRecordMatchSource): TV3FeedbackRecordMatch => ({
+  feedback_record_id: match.feedback_record_id,
+  score: match.score,
+  field_label: match.field_label,
+  value_text: match.value_text,
+});
+
+export type TV3FeedbackDataset = {
+  id: string;
+  name: string;
+};
+
+export const serializeV3FeedbackDataset = (dataset: { id: string; name: string }): TV3FeedbackDataset => ({
+  id: dataset.id,
+  name: dataset.name,
+});

diff --git a/apps/web/app/api/v3/feedbackRecords/lib/serializers.test.ts b/apps/web/app/api/v3/feedbackRecords/lib/serializers.test.ts
--- a/apps/web/app/api/v3/feedbackRecords/lib/serializers.test.ts
+++ b/apps/web/app/api/v3/feedbackRecords/lib/serializers.test.ts
@@ -0,0 +1,156 @@
+import { describe, expect, test } from "vitest";
+import type { FeedbackRecordData } from "@/modules/hub/types";
+import {
+  serializeV3FeedbackDataset,
+  serializeV3FeedbackRecord,
+  serializeV3FeedbackRecordMatch,
+} from "./serializers";
+
+/**
+ * The serializer is an explicit allowlist, so the risk it carries is *silent omission*: dropping a field
+ * still returns a valid-looking record. These tests pin the whole field set, not a sample.
+ */
+const fullRecord: FeedbackRecordData = {
+  id: "019fa338-f494-7384-b34e-01739783d280",
+  tenant_id: "clfd1234567890123456789012",
+  submission_id: "sub-1",
+  source_type: "survey",
+  source_id: "svy_1",
+  source_name: "Q1 NPS",
+  field_id: "q1",
+  field_type: "text",
+  field_label: "What can we improve?",
+  field_group_id: "grp_1",
+  field_group_label: "Group",
+  user_id: "user-1",
+  language: "en",
+  value_text: "Great support",
+  value_number: 9,
+  value_boolean: true,
+  value_date: "2026-07-01T00:00:00.000Z",
+  value_id: "opt_1",
+  metadata: { device: "ios" },
+  sentiment: "positive",
+  sentiment_score: 0.8,
+  emotions: ["joy"],
+  translation_lang_key: "de-DE",
+  value_text_translated: "Guter Support",
+  collected_at: "2026-07-01T00:00:00.000Z",
+  created_at: "2026-07-01T00:00:00.000Z",
+  updated_at: "2026-07-01T00:00:00.000Z",
+} as FeedbackRecordData;
+
+describe("serializeV3FeedbackRecord", () => {
+  test("emits every allowlisted field, with the tenant renamed to dataset_id", () => {
+    // Asserted as a whole object: a dropped field or a leaked extra both fail here.
+    expect(serializeV3FeedbackRecord(fullRecord)).toEqual({
+      id: fullRecord.id,
+      dataset_id: "clfd1234567890123456789012",
+      submission_id: "sub-1",
+      source_type: "survey",
+      source_id: "svy_1",
+      source_name: "Q1 NPS",
+      field_id: "q1",
+      field_type: "text",
+      field_label: "What can we improve?",
+      field_group_id: "grp_1",
+      field_group_label: "Group",
+      user_id: "user-1",
+      language: "en",
+      value_text: "Great support",
+      value_number: 9,
+      value_boolean: true,
+      value_date: "2026-07-01T00:00:00.000Z",
+      value_id: "opt_1",
+      metadata: { device: "ios" },
+      sentiment: "positive",
+      sentiment_score: 0.8,
+      emotions: ["joy"],
+      translation_lang_key: "de-DE",
+      value_text_translated: "Guter Support",
+      collected_at: "2026-07-01T00:00:00.000Z",
+      created_at: "2026-07-01T00:00:00.000Z",
+      updated_at: "2026-07-01T00:00:00.000Z",
+    });
+  });
+
+  test("never emits tenant_id", () => {
+    const dto = serializeV3FeedbackRecord(fullRecord);
+
+    expect(dto).not.toHaveProperty("tenant_id");
+    expect(JSON.stringify(dto)).not.toContain("tenant_id");
+  });
+
+  test("drops anything outside the allowlist, so an SDK addition can't widen the response", () => {
+    const withExtras = {
+      ...fullRecord,
+      internal_debug_note: "should not surface",
+      hub_only_column: 42,
+    } as unknown as FeedbackRecordData;
+
+    const dto = serializeV3FeedbackRecord(withExtras) as Record<string, unknown>;
+
+    expect(dto.internal_debug_note).toBeUndefined();
+    expect(dto.hub_only_column).toBeUndefined();
+  });
+
+  test("omits absent fields rather than emitting undefined, and preserves explicit nulls", () => {
+    const sparse = {
+      id: fullRecord.id,
+      tenant_id: "clfd1234567890123456789012",
+      value_text: null,
+    } as unknown as FeedbackRecordData;
+
